"use client";

import React from "react";
import { ExplainerClip } from "../../types/schema";
import { ClipPlayer } from "../engine/ClipPlayer";
import { useActiveClip } from "../../hooks/UseActiveClip";

interface Props {
  clips: ExplainerClip[];
}

export const ClipFeed: React.FC<Props> = ({ clips }) => {
  const { containerRef, activeIndex } = useActiveClip(clips.length);

  return (
    <div
      ref={containerRef}
      className="h-screen w-full overflow-y-scroll snap-y snap-mandatory
                 scroll-smooth bg-ink-950
                 [scrollbar-width:none] [-ms-overflow-style:none]
                 [&::-webkit-scrollbar]:hidden"
    >
      {clips.map((clip, i) => (
        <section
          key={clip.id}
          data-clip-index={i}
          className="h-screen w-full snap-start snap-always
                     flex items-center justify-center p-4"
        >
          <ClipPlayer clip={clip} isActive={i === activeIndex} />
        </section>
      ))}
    </div>
  );
};
