'use client';

import { useEffect, useRef, useState } from 'react';

/**
 * Watches a list of scroll-snap children and reports which one
 * is currently filling the viewport.
 */
export function useActiveClip(count: number) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const items = Array.from(
      container.querySelectorAll<HTMLElement>('[data-clip-index]')
    );
    if (items.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            const idx = Number(entry.target.getAttribute('data-clip-index'));
            setActiveIndex(idx);
          }
        });
      },
      {
        root: container,      // measure against the feed, not the window
        threshold: 0.6,       // 60% visible = this is the active clip
      }
    );

    items.forEach((item) => observer.observe(item));
    return () => observer.disconnect();   // cleanup — same discipline as your timers
  }, [count]);

  return { containerRef, activeIndex };
}